use mill.stock;
use mill.rules;

pub fn lines() -> String {
    let planks = mill.stock.inventory();
    var labels: List<String> = [];
    var index = 0;

    while index < planks.len() {
        match planks.get(index) {
            Some(plank) => {
                if mill.rules.is_kept(plank) {
                    labels.push(mill.rules.to_label(plank));
                }
                unit
            },
            None => unit,
        };
        index = index + 1;
    }

    labels.join(",")
}

