use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.signals();
    var rendered: List<String> = [];
    var index = 0;
    while index < signals.len() {
        let entry = match signals.get(index) {
            Some(harbor.signal.Signal.Calm) => "calm",
            Some(harbor.signal.Signal.Gale(speed)) => "gale:".concat(speed.to_text()),
            Some(harbor.signal.Signal.Fog(density)) => "fog:".concat(density),
            None => "",
        };
        rendered.push(entry);
        index = index + 1;
    }
    rendered.join(";")
}

