use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var index = 0;

    while index < frames.len() {
        let value = match frames.get(index) {
            Some(frame) => match relay.feed.try_decode(frame) {
                Ok(decoded) => decoded,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        index = index + 1;
    }

    relay.feed.emit(io: io, total: total)?;
    return Ok(unit);
}

