use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let ponies = stable.herd.lineup();
    var entries: List<String> = [];
    var index = 0;
    while index < ponies.len() {
        match ponies.get(index) {
            Some(pony) => {
                let fed = stable.herd.feed(pony: pony, scoops: 3);
                entries.push(stable.ledger.render(fed));
            },
            None => {
                break;
            },
        };
        index = index + 1;
    }
    io.write(text: entries.join(","))?;
    return Ok(unit);
}

