use galley.menu;
use galley.kitchen;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let board = galley.menu.board();
    var index = 0;

    while index < board.len() {
        match board.get(index) {
            Some(dish) => {
                if index > 0 {
                    io.write(text: ";")?;
                }
                galley.kitchen.serve(io: io, dish: dish)?;
            },
            None => unit,
        };
        index = index + 1;
    }

    return Ok(unit);
}
